param(
  [string]$DxvkDll,
  [string]$Dxvk32Dll,
  [string]$VcVarsVer = '14.29',
  [string]$UpstreamCommit = 'cf83c0514d5690a2e54369ba24a6d044b989e6c8'
)
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
# Validate before fetching a backend or preparing any source. Both runtime guards
# use the full selected upstream SHA, including explicit validation overrides.
$env:L4D2_BRIDGE_BUILD_ID = & python "$PSScriptRoot/build_identity.py" --upstream-commit $UpstreamCommit
if ($LASTEXITCODE -ne 0) { throw 'Invalid upstream build identity' }
if (-not $DxvkDll) { $DxvkDll = & "$PSScriptRoot/prepare_backend.ps1" -VcVarsVer $VcVarsVer }
if (-not $Dxvk32Dll) { $Dxvk32Dll = & "$PSScriptRoot/prepare_backend.ps1" -Architecture x86 -VcVarsVer $VcVarsVer }
$dxvkPath = (Resolve-Path $DxvkDll).Path
$dxvk32Path = (Resolve-Path $Dxvk32Dll).Path
function Invoke-Checked {
  param([string]$Program, [string[]]$Arguments)
  & $Program @Arguments
  if ($LASTEXITCODE -ne 0) { throw "$Program failed: $LASTEXITCODE" }
}
Invoke-Checked 'python' @("$PSScriptRoot/prepare_bridge.py", "--commit", $UpstreamCommit)
$source = Join-Path $repoRoot '.deps/dxvk-remix'
Push-Location (Join-Path $source 'bridge')
try {
  # Each architecture gets a fresh PowerShell process and its own MSVC environment.
  foreach ($arch in @('x64', 'x86')) {
    $buildCommand = ". .\build_common.ps1; SetupVS -Platform $arch -VcVarsVer $VcVarsVer; & meson setup _compRelease_$arch --buildtype release --backend ninja; if (`$LASTEXITCODE -ne 0) { exit `$LASTEXITCODE }; Copy-Item Directory.Build.Props _compRelease_$arch; & meson compile -C _compRelease_$arch; exit `$LASTEXITCODE"
    Invoke-Checked 'powershell.exe' @('-NoProfile', '-Command', $buildCommand)
  }
  # The separate server build keeps SERVER channel semantics out of the x86 Client.
  $buildCommand = ". .\build_common.ps1; SetupVS -Platform x86 -VcVarsVer $VcVarsVer; & meson setup _compRelease_x86_server --buildtype release --backend ninja -Dexperimental_x86_server=true; if (`$LASTEXITCODE -ne 0) { exit `$LASTEXITCODE }; & meson compile -C _compRelease_x86_server; exit `$LASTEXITCODE"
  Invoke-Checked 'powershell.exe' @('-NoProfile', '-Command', $buildCommand)
} finally { Pop-Location }
Invoke-Checked 'powershell.exe' @('-NoProfile', '-File', "$PSScriptRoot/build_l4n_plugin.ps1")
Invoke-Checked 'python' @("$PSScriptRoot/package_release.py", '--source', $source, '--dxvk', $dxvkPath,
  '--dxvk-x86', $dxvk32Path, '--plugin', (Join-Path $repoRoot '.deps/l4n-plugin/L4D2BridgePlugin.dll'))

